<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
const newId=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('');
const clone=(value:any)=>JSON.parse(JSON.stringify(value));
type Row={id:string;data:any;createdAt:string};
const token=ref(sessionStorage.getItem('tailor-token')||'');
const state=ref<Record<string,any[]>>({profiles:[],templates:[],jobs:[],resumes:[],evidence:[],applications:[],imports:[],tasks:[]});
const tab=ref('workspace'),message=ref(''),error=ref(''),busy=ref(false),connected=ref(false);
const profileId=ref(''),jobId=ref(''),templateId=ref(''),resumeId=ref(''),prompt=ref('Write a professional English resume. Emphasize verified experience relevant to this job.'),maxPages=ref(2);
const jobText=ref(''),jobURL=ref(''),jobAssetId=ref(''),jobImage=ref('');
const preview=ref(''),chat=ref(''),changes=ref(false),approved=ref(false),comparison=ref<any>(null),activeTask=ref<any>(null);
const editor=ref<any>({name:'',email:'',phone:'',location:'',links:[],facts:[]}),importId=ref(''),profileParent=ref(''),confirmed=ref(false);
const template=ref<any>(null),unlock=ref(false),repository=ref(''),watcherSearch=ref(''),watcherPage=ref(1),watcherResults=ref<any>(null);
const importDetail=ref<any>(null);
let importLoadSequence=0;
const applicationStatus=ref('prepared'),applicationNotes=ref('');
const selectedResume=computed(()=>state.value.resumes.find((r:Row)=>r.id===resumeId.value));
const originallyLocked=computed(()=>!!state.value.templates.find((t:Row)=>t.id===templateId.value)?.data.config.locked);
const selectedJob=computed(()=>state.value.jobs.find((r:Row)=>r.id===jobId.value));
const selectedImport=computed(()=>state.value.imports.find((r:Row)=>r.id===importId.value));
let timer:ReturnType<typeof setTimeout>|undefined;
async function api(path:string,method='GET',body?:any){const headers:Record<string,string>={Authorization:`Bearer ${token.value}`};if(body&&!(body instanceof FormData))headers['Content-Type']='application/json';const res=await fetch('/v1'+path,{method,headers,body:body instanceof FormData?body:body?JSON.stringify(body):undefined});if(!res.ok){let m='';try{m=(await res.json()).message}catch{}throw new Error(m||`HTTP ${res.status}`)}return res.json();}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function refresh(){state.value=await api('/state');if(!profileId.value&&state.value.profiles[0])profileId.value=state.value.profiles[0].id;if(!templateId.value&&state.value.templates[0])templateId.value=state.value.templates[0].id;}
async function connect(){await run(async()=>{sessionStorage.setItem('tailor-token',token.value);await refresh();connected.value=true;message.value='Connected · ข้อมูลประวัติและการสร้าง Resume ประมวลผลในเครื่อง';const pending=state.value.tasks.find(t=>['queued','running'].includes(t.status));if(pending)track(pending);});}
async function upload(file:File){const form=new FormData();form.append('file',file);return api('/assets','POST',form)}
function fileFrom(e:Event){return (e.target as HTMLInputElement).files?.[0]}
async function importResume(e:Event){const f=fileFrom(e);if(!f)return;await run(async()=>{const asset=await upload(f);track(await api('/resumes/import','POST',{assetId:asset.id}));message.value='กำลังอ่าน Resume และวิเคราะห์ดีไซน์…';});}
async function attachJob(file:File){await run(async()=>{const asset=await upload(file);jobAssetId.value=asset.id;if(jobImage.value)URL.revokeObjectURL(jobImage.value);jobImage.value=file.type.startsWith('image/')?URL.createObjectURL(file):'';message.value='แนบประกาศงานแล้ว';});}
function paste(e:ClipboardEvent){const f=Array.from(e.clipboardData?.items||[]).find(x=>x.type.startsWith('image/'))?.getAsFile();if(f){e.preventDefault();void attachJob(f)}}
function track(task:any){activeTask.value=task;if(timer)clearTimeout(timer);timer=setTimeout(()=>void poll(),1200)}
async function poll(){try{const task=await api('/tasks/'+activeTask.value.id);activeTask.value=task;if(['queued','running'].includes(task.status)){timer=setTimeout(()=>void poll(),1500);return}await refresh();if(task.status==='failed'){error.value=task.error;return}const out=task.output;if(out.importId){tab.value='profile';await loadImport(out.importId);}if(out.jobId)jobId.value=out.jobId;if(out.resumeId){resumeId.value=out.resumeId;tab.value='workspace';}if(out.evidenceId)tab.value='evidence';if(out.assetId)await download(out.assetId);if(out.original)comparison.value=out;message.value='งานเสร็จแล้ว';}catch(e){error.value=(e as Error).message;}}
async function loadImport(id:string){
 const row=state.value.imports.find((r:Row)=>r.id===id);
 if(!row)return;
 const request=++importLoadSequence;
 importId.value=id;
 importDetail.value=null;
 try{
  // Read original text and preview on demand, not as part of every /v1/state request.
  const detail=await api('/imports/'+id);
  if(request!==importLoadSequence||importId.value!==id)return;
  if(!detail?.data?.profile||!Array.isArray(detail.data.profile.facts))throw new Error('ข้อมูลนำเข้าไม่ครบ');
  editor.value=clone(detail.data.profile);
  profileParent.value='';
  confirmed.value=false;
  templateId.value=detail.data.templateId||templateId.value;
  importDetail.value=detail;
 }catch(e){
  if(request===importLoadSequence)error.value='เปิดรายละเอียด Resume ไม่สำเร็จ: '+(e as Error).message;
 }
}
function loadProfile(id:string){const r=state.value.profiles.find((r:Row)=>r.id===id);if(r){++importLoadSequence;importDetail.value=null;editor.value=clone(r.data.profile);profileParent.value=id;importId.value=r.data.importId||'';confirmed.value=false;}}
function addFact(){editor.value.facts.push({id:newId(),section:'projects',group:'',heading:'',detail:'',source:'User statement',verified:false})}
async function saveProfile(){await run(async()=>{const r=await api('/profiles/master','POST',{profile:editor.value,confirmed:confirmed.value,...(profileParent.value?{parentId:profileParent.value}:{}),...(importId.value?{importId:importId.value}:{})});profileId.value=r.id;profileParent.value=r.id;await refresh();message.value='บันทึก Master Resume เวอร์ชันใหม่แล้ว';});}
async function analyze(){await run(async()=>track(await api('/jobs/analyze','POST',{text:jobText.value,...(jobURL.value?{url:jobURL.value}:{}),...(jobAssetId.value?{assetId:jobAssetId.value}:{})})));}
async function generate(){await run(async()=>track(await api('/resumes/tailor','POST',{profileId:profileId.value,jobId:jobId.value,templateId:templateId.value,prompt:prompt.value,maxPages:maxPages.value})));}
async function revise(){await run(async()=>{track(await api(`/resumes/${resumeId.value}/revise`,'POST',{prompt:chat.value,templateId:templateId.value}));chat.value=''});}
async function approve(){await run(async()=>{await api(`/resumes/${resumeId.value}/approve`,'POST',{reviewedAllClaims:true});approved.value=true;message.value='ยืนยันข้อความในเวอร์ชันนี้แล้ว';});}
async function exportFile(format:string){await run(async()=>track(await api(`/resumes/${resumeId.value}/export`,'POST',{format})));}
async function download(id:string){const res=await fetch('/v1/assets/'+id,{headers:{Authorization:`Bearer ${token.value}`}});if(!res.ok)throw new Error('Download failed');const url=URL.createObjectURL(await res.blob());const a=document.createElement('a');a.href=url;const header=res.headers.get('content-disposition')||'';a.download=decodeURIComponent(header.split("UTF-8''")[1]||'resume');a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function saveTemplate(){await run(async()=>{const r=await api('/templates','POST',{config:template.value,parentId:templateId.value,unlock:unlock.value});await refresh();templateId.value=r.id;unlock.value=false;message.value='บันทึก Template ใหม่แล้ว ใช้ Generate หรือส่งคำสั่งแก้ไขเพื่อสร้าง Resume กับ Template นี้';});}
async function browseWatcher(){await run(async()=>{watcherResults.value=await api(`/integrations/job-watcher?search=${encodeURIComponent(watcherSearch.value)}&page=${watcherPage.value}`)});}
async function importWatcher(id:string){await run(async()=>track(await api('/integrations/job-watcher/import','POST',{externalId:id})));}
function factSource(id:string){return selectedResume.value?.data.profile.facts.find((f:any)=>f.id===id)?.detail||'Unknown fact'}
function useEvidence(e:Row){if(e.data.candidateFacts?.length){editor.value.facts.push(...clone(e.data.candidateFacts).map((f:any)=>({...f,id:newId(),verified:false})));tab.value='profile';message.value='เพิ่มข้อเสนอจาก README แล้ว ตรวจและแก้ให้ตรงกับส่วนที่คุณทำจริงก่อนยืนยัน';return;}editor.value.facts.push({id:newId(),section:'projects',group:e.data.repository,heading:'',detail:'',source:`${e.data.url} @ ${e.data.commit}`,verified:false});tab.value='profile';message.value='ระบุส่วนที่คุณทำจริง แล้วตรวจยืนยันก่อนบันทึก';}
watch(templateId,()=>{const r=state.value.templates.find((r:Row)=>r.id===templateId.value);template.value=r?clone(r.data.config):null;unlock.value=false;});
let previewSequence=0;
watch(resumeId,async()=>{approved.value=false;comparison.value=null;const seq=++previewSequence;if(!resumeId.value){preview.value='';return}await run(async()=>{const r=await api(`/resumes/${resumeId.value}/preview`);if(seq===previewSequence)preview.value=r.html;});});
onMounted(()=>{if(token.value)void connect()});onUnmounted(()=>{if(timer)clearTimeout(timer);if(jobImage.value)URL.revokeObjectURL(jobImage.value)});
</script>

<template>
<div class="app">
<header class="topbar"><div class="brand"><span class="mark">R</span><div><b>Resume Tailor</b><small>LOCAL AI · YOUR EXPERIENCE, CLEARLY TOLD</small></div></div><span class="local"><i></i> {{connected?'Local workspace':'Connect your workspace'}}</span></header>
<div v-if="!connected" class="connect card"><p class="eyebrow">WELCOME TO YOUR CAREER WORKSPACE</p><h1>ประสบการณ์ของคุณ<br>เล่าให้ตรงกับงานที่ใช่</h1><p>อัปโหลดครั้งเดียว ปรับ Resume พร้อมดีไซน์เดิม และตรวจหลักฐานก่อนส่งออก</p><label>API token จากไฟล์ .env<input v-model="token" type="password" placeholder="วาง API_TOKEN" @keyup.enter="connect"></label><button class="primary" @click="connect" :disabled="busy">เชื่อมต่อ Workspace →</button><p class="error" v-if="error">{{error}}</p></div>
<template v-else>
<nav><button v-for="[id,label] in [['workspace','สร้าง Resume'],['profile','ประวัติจริง'],['templates','ดีไซน์'],['evidence','GitHub / หลักฐาน'],['watcher','Job-Watcher'],['history','ประวัติ / สมัครงาน']]" :class="{active:tab===id}" @click="tab=id">{{label}}</button><button class="refresh" @click="run(refresh)">↻ Refresh</button></nav>
<div class="notice error" v-if="error">{{error}} <button @click="error=''">×</button></div><div class="notice" v-else-if="message">{{message}}</div>
<div v-if="activeTask&&['queued','running','failed'].includes(activeTask.status)" class="taskbar">{{activeTask.type}} · {{activeTask.status}} <span v-if="activeTask.status==='running'">กำลังประมวลผล งาน AI อาจใช้เวลาหลายนาที</span><button v-if="activeTask.status==='failed'" @click="run(async()=>track(await api('/tasks/'+activeTask.id+'/retry','POST')))">ลองอีกครั้ง</button></div>
<main v-if="tab==='workspace'">
<div class="page-title"><div><p class="eyebrow">FROM EXPERIENCE TO OPPORTUNITY</p><h1>สร้าง Resume สำหรับงานถัดไป</h1></div><span class="pill">ข้อมูลจริง · ดีไซน์ของคุณ</span></div>
<div class="workspace">
<section class="card inputs"><div class="section-title"><span class="step">01</span><h2>ประกาศรับสมัครงาน</h2></div><div class="paste" @paste="paste" tabindex="0"><textarea v-model="jobText" @paste="paste" placeholder="วางข้อความประกาศงาน หรือคลิกที่นี่แล้ว Ctrl+V ภาพ"></textarea><img v-if="jobImage" :src="jobImage" class="job-image"><label class="upload">＋ รูปภาพ / PDF<input type="file" accept="image/png,image/jpeg,application/pdf" @change="e=>{const f=fileFrom(e);if(f)attachJob(f)}"></label><button v-if="jobAssetId" @click="jobAssetId='';jobImage=''">ลบไฟล์แนบ</button></div><input v-model="jobURL" placeholder="หรือ URL ประกาศงาน (HTTPS)"><button class="secondary full" @click="analyze" :disabled="busy">วิเคราะห์ประกาศงาน</button><label>งานที่วิเคราะห์แล้ว<select v-model="jobId"><option value="">เลือกงาน</option><option v-for="j in state.jobs" :value="j.id">{{j.data.company}} · {{j.data.title}}</option></select></label><div v-if="selectedJob" class="skills"><small>REQUIRED SKILLS</small><span v-for="s in selectedJob.data.required" :key="s" class="chip">{{s}}</span></div>
<hr><div class="section-title"><span class="step">02</span><h2>Resume และ Template</h2></div><label class="upload large">↑ นำเข้า Resume เดิม<input type="file" accept=".pdf,.docx,.png,.jpg,.jpeg" @change="importResume"></label><select v-model="profileId"><option value="">เลือก Master Resume</option><option v-for="p in state.profiles" :value="p.id">{{p.data.profile.name}} · {{new Date(p.createdAt).toLocaleString()}}</option></select><select v-model="templateId"><option v-for="t in state.templates" :value="t.id">{{t.data.config.name}} {{t.data.config.locked?'🔒':''}}</option></select></section>
<section class="card editor-panel"><div class="section-title"><span class="step">03</span><h2>ปรับเนื้อหาด้วย AI</h2></div><p class="muted">เลือกและเรียบเรียงจากประวัติที่ยืนยันแล้ว</p><textarea v-model="prompt" rows="5"></textarea><label class="inline">จำนวนหน้าสูงสุด<input v-model.number="maxPages" type="number" min="1" max="5"></label><button class="primary full" @click="generate" :disabled="busy||!profileId||!jobId||!templateId">Generate Resume ↗</button><div v-if="selectedResume" class="review"><h3>{{selectedResume.data.tailored.targetRole}}</h3><p>{{selectedResume.data.tailored.summary.text}}</p><div class="warning" v-if="selectedResume.data.matching.missing.length"><b>ยังไม่พบหลักฐานสำหรับ</b><p>{{selectedResume.data.matching.missing.join(' · ')}}</p></div><p class="muted" v-for="n in selectedResume.data.tailored.notes">{{n}}</p><button @click="changes=!changes">{{changes?'ซ่อน':'View Changes / ตรวจหลักฐาน'}}</button><div v-if="changes" class="diff"><h4>Summary</h4><p v-for="id in selectedResume.data.tailored.summary.sourceFactIds" class="before">{{factSource(id)}}</p><p class="after">{{selectedResume.data.tailored.summary.text}}</p><article v-for="item in selectedResume.data.tailored.items"><small>{{item.sourceFactId}}</small><p class="before">{{factSource(item.sourceFactId)}}</p><p class="after">{{item.text}}</p></article><h4>ไม่ได้เลือกมาใช้</h4><p v-for="f in selectedResume.data.profile.facts.filter((f:any)=>!selectedResume.data.tailored.items.some((i:any)=>i.sourceFactId===f.id))">{{f.detail}}</p></div><div class="chat-box"><textarea v-model="chat" placeholder="เช่น เน้น React มากขึ้น หรือลดให้เหลือหน้าเดียว" rows="3"></textarea><button @click="revise" :disabled="busy||!chat.trim()">ส่งคำสั่งแก้ไข →</button></div><p class="muted">ทุกคำสั่งสร้างเวอร์ชันใหม่ ต้องตรวจยืนยันอีกครั้งก่อน Export</p></div><div v-else class="empty"><span>✦</span><p>Resume ฉบับใหม่เริ่มจาก<br>ประสบการณ์จริงของคุณ</p></div></section>
<section class="preview-panel"><div class="preview-top"><h2>Live Preview</h2><select v-model="resumeId"><option value="">เลือกฉบับที่สร้าง</option><option v-for="r in state.resumes" :value="r.id">{{r.data.job.company}} · {{new Date(r.createdAt).toLocaleString()}}</option></select></div><iframe v-if="preview" :srcdoc="preview" sandbox="" title="Resume A4 preview"></iframe><div v-else class="paper-placeholder"><div></div><i></i><i></i><h3>YOUR NEXT CHAPTER</h3><p>ตัวอย่าง Resume จะแสดงที่นี่</p><i></i><i></i><i></i></div><div v-if="resumeId" class="export-bar"><label><input type="checkbox" :checked="approved" @change="e=>{if((e.target as HTMLInputElement).checked)approve();else approved=false}"> ฉันตรวจข้อความและหลักฐานในฉบับนี้แล้ว</label><div><button @click="exportFile('pdf')" :disabled="!approved||busy" class="primary">↓ PDF</button><button @click="exportFile('docx')" :disabled="!approved||busy">↓ DOCX</button><button @click="run(async()=>track(await api('/resumes/'+resumeId+'/compare','POST')))">เทียบดีไซน์</button></div><small>DOCX เป็นรูปแบบแก้ไขได้แบบคอลัมน์เดียว</small></div></section>
</div><section v-if="comparison" class="card comparison"><h2>Original / Generated / Difference</h2><p>{{comparison.metric}}</p><p>Pixel agreement: {{comparison.pixelAgreement}}% — ไม่ใช่คะแนนคุณภาพหรือ ATS</p><div><img v-for="k in ['original','generated','difference']" :src="'data:image/png;base64,'+comparison[k]"></div></section></main>
<main v-if="tab==='profile'"><div v-if="selectedImport?.data.warnings?.length" class="notice"><strong>ผลการนำเข้า:</strong> {{selectedImport.data.diagnostics?.contentChunks||0}} ส่วนข้อความ · {{selectedImport.data.diagnostics?.fallbackChunks||0}} ส่วนต้องตรวจเอง <details><summary>คำเตือน ({{selectedImport.data.warnings.length}})</summary><p v-for="(warning,idx) in selectedImport.data.warnings" :key="idx">{{warning}}</p></details></div><div class="page-title"><div><p class="eyebrow">MASTER RESUME</p><h1>ฐานข้อมูลประวัติจริง</h1></div><label class="upload">↑ PDF / DOCX / ภาพ<input type="file" accept=".pdf,.docx,.png,.jpg,.jpeg" @change="importResume"></label></div><div class="two-grid"><section class="card"><h2>ข้อมูลส่วนตัว</h2><select @change="e=>loadProfile((e.target as HTMLSelectElement).value)"><option value="">เลือกโปรไฟล์ที่เคยบันทึก</option><option v-for="p in state.profiles" :value="p.id">{{p.data.profile.name}} · {{new Date(p.createdAt).toLocaleString()}}</option></select><select @change="e=>loadImport((e.target as HTMLSelectElement).value)"><option value="">เลือกผลนำเข้า</option><option v-for="i in state.imports" :value="i.id">{{i.data.profile.name}} · {{new Date(i.createdAt).toLocaleString()}}</option></select><label v-for="[key,label] in [['name','ชื่อ'],['email','อีเมล'],['phone','โทรศัพท์'],['location','ที่อยู่']]">{{label}}<input v-model="editor[key]"></label><label>ลิงก์ (คั่นด้วย comma)<input :value="editor.links.join(', ')" @input="e=>editor.links=(e.target as HTMLInputElement).value.split(',').map(x=>x.trim()).filter(Boolean)"></label><div v-if="importDetail?.data?.extraction"><p class="warning" v-for="w in importDetail.data.extraction.warnings">{{w}}</p><img class="original" v-for="p in importDetail.data.extraction.previews" :src="'data:image/png;base64,'+p"><details><summary>ข้อความจากต้นฉบับ</summary><pre>{{importDetail.data.extraction.text}}</pre></details></div></section><section class="card"><div class="section-title"><h2>ข้อเท็จจริงและหลักฐาน</h2><button @click="addFact">＋ เพิ่ม</button></div><p class="muted">AI ใช้เฉพาะรายการที่คุณติ๊กยืนยัน ชื่อตำแหน่งเดิม วันที่ และบริษัทควรอยู่ในหัวข้อ / กลุ่ม</p><article v-for="(f,index) in editor.facts" :key="f.id" class="fact"><div class="row"><select v-model="f.section"><option v-for="s in ['summary','skills','work','projects','education','certificates','languages']">{{s}}</option></select><button @click="editor.facts.splice(index,1)">ลบ</button></div><input v-model="f.group" placeholder="กลุ่ม เช่น บริษัท / โปรเจกต์"><input v-model="f.heading" placeholder="หัวข้อ เช่น ตำแหน่งเดิม และวันที่"><textarea v-model="f.detail" placeholder="สิ่งที่คุณทำจริง" rows="3"></textarea><textarea v-model="f.source" placeholder="หลักฐาน / ข้อความอ้างอิง" rows="2"></textarea><label class="inline"><input type="checkbox" v-model="f.verified"> ยืนยันข้อเท็จจริงนี้</label></article><label class="inline"><input type="checkbox" v-model="confirmed"> ฉันตรวจประวัติและรายการที่ยืนยันแล้ว</label><button class="primary" @click="saveProfile" :disabled="busy||!confirmed||!editor.name">บันทึก Master Resume เวอร์ชันใหม่</button></section></div></main>
<main v-if="tab==='templates'"><div class="page-title"><div><p class="eyebrow">TEMPLATE LIBRARY</p><h1>ดีไซน์ที่ใช้ซ้ำได้</h1></div></div><div class="two-grid"><section class="card"><select v-model="templateId"><option v-for="t in state.templates" :value="t.id">{{t.data.config.name}} · {{t.id.slice(0,8)}}</option></select><template v-if="template"><label v-if="originallyLocked" class="warning inline"><input type="checkbox" v-model="unlock"> ปลดล็อกเพื่อแก้ไขและสร้างเวอร์ชันใหม่</label><fieldset :disabled="originallyLocked&&!unlock"><label>ชื่อ<input v-model="template.name"></label><label>Layout<select v-model="template.layout"><option value="single">Single column / ATS</option><option value="sidebar">Sidebar / 2 columns</option></select></label><label>กระดาษ<select v-model="template.paper"><option>A4</option><option>Letter</option></select></label><label>ฟอนต์<select v-model="template.font"><option>Arial</option><option>Georgia</option><option>Noto Sans Thai</option></select></label><label v-for="[key,label] in [['accent','สีหัวข้อ'],['background','พื้นหลัง Sidebar']]">{{label}}<input type="color" v-model="template[key]"></label><label v-for="[key,label,min,max] in [['bodySize','ขนาดข้อความ (pt)',9,14],['nameSize','ขนาดชื่อ (pt)',16,36],['margin','ขอบกระดาษ (mm)',8,25],['sidebarWidth','Sidebar (%)',25,40],['gap','ช่องว่าง Section (mm)',2,12]]">{{label}}<input type="number" v-model.number="template[key]" :min="min" :max="max" step="0.5"></label><label>ลำดับ Section (คั่นด้วย comma)<input :value="template.sections.join(', ')" @change="e=>template.sections=(e.target as HTMLInputElement).value.split(',').map(x=>x.trim()).filter(Boolean)"></label><label class="inline"><input type="checkbox" v-model="template.locked"> ล็อก Template</label></fieldset><button class="primary" @click="saveTemplate" :disabled="busy||(originallyLocked&&!unlock)">บันทึกเวอร์ชันใหม่</button></template></section><section class="card"><h2>ดีไซน์แยกจากเนื้อหา</h2><p>นำเข้า Resume จากหน้าประวัติจริง ระบบจะอ่านสี ฟอนต์ พิกัด และตีความโครงสร้างเพื่อสร้าง Template ที่แก้ไขได้</p><p>Template รองรับคอลัมน์เดียวและ Sidebar การตกแต่งซับซ้อน รูปถ่าย และไอคอนยังต้องนำมาปรับเพิ่มเองในโค้ด Renderer</p><p>เลือก Template แล้ว Generate หรือส่งคำสั่งใน Chat เพื่อสร้างฉบับใหม่ จากนั้นกด “เทียบดีไซน์” เพื่อดูภาพจริงและความต่าง</p><p>การเปรียบเทียบใช้หน้าแรกและได้รับผลจากข้อความที่เปลี่ยนไป ไม่ได้รับประกันความเหมือนต้นฉบับ</p></section></div></main>
<main v-if="tab==='evidence'"><div class="page-title"><div><p class="eyebrow">EVIDENCE VAULT</p><h1>หลักฐานจากโปรเจกต์จริง</h1></div></div><section class="card"><div class="row"><input v-model="repository" placeholder="owner/repository"><button class="primary" @click="run(async()=>track(await api('/integrations/github','POST',{repository})))" :disabled="busy||!repository">อ่าน GitHub</button></div><p class="muted">ดึง README ที่ผูกกับ commit SHA ไม่ถือว่าโค้ดทั้งหมดเป็นผลงานของคุณโดยอัตโนมัติ</p></section><section class="card evidence" v-for="e in state.evidence"><h2>{{e.data.repository}}</h2><small>{{e.data.commit}}</small><p>{{e.data.warning}}</p><details><summary>อ่าน README</summary><pre>{{e.data.readme}}</pre></details><button @click="useEvidence(e)">เพิ่มเป็นข้อเท็จจริงรอตรวจ</button></section></main>
<main v-if="tab==='watcher'"><div class="page-title"><div><p class="eyebrow">JOB-WATCHER INTEGRATION</p><h1>เลือกงาน แล้วสร้าง Resume</h1></div></div><section class="card"><div class="row"><input v-model="watcherSearch" placeholder="ค้นหา เช่น NestJS"><button class="primary" @click="watcherPage=1;browseWatcher()">ค้นหางาน</button></div><p class="muted">เชื่อมกับ JOB_WATCHER_BASE_URL ที่กำหนดใน .env · งานย้อนหลัง 30 วัน</p><div v-if="watcherResults"><article v-for="j in watcherResults.items" class="job-row"><div><h3>{{j.title}}</h3><p>{{j.company}} · {{j.location}}</p><span class="chip" v-for="t in j.technologies">{{t}}</span></div><div><button @click="importWatcher(j.id)" :disabled="busy">นำเข้าและวิเคราะห์ →</button><button class="primary" :disabled="busy||!profileId||!templateId" @click="run(async()=>track(await api('/integrations/job-watcher/tailor','POST',{externalId:j.id,profileId,templateId,prompt,maxPages})))">สร้าง Resume งานนี้</button></div></article><div class="row"><button :disabled="watcherPage<=1" @click="watcherPage--;browseWatcher()">ก่อนหน้า</button><span>หน้า {{watcherPage}} / {{watcherResults.pagination.totalPages}}</span><button :disabled="watcherPage>=watcherResults.pagination.totalPages" @click="watcherPage++;browseWatcher()">ถัดไป</button></div></div></section></main>
<main v-if="tab==='history'"><div class="page-title"><div><p class="eyebrow">VERSIONS & APPLICATIONS</p><h1>ทุกฉบับ ทุกโอกาส</h1></div></div><div class="two-grid"><section class="card"><h2>Resume Versions</h2><article class="job-row" v-for="r in state.resumes"><div><h3>{{r.data.job.company}} · {{r.data.job.title}}</h3><small>{{new Date(r.createdAt).toLocaleString()}} · {{r.data.model}}</small><p>{{r.data.request.prompt}}</p><small v-if="r.data.parentId">ฉบับก่อน: {{r.data.parentId.slice(0,8)}}</small></div><button @click="resumeId=r.id;tab='workspace'">เปิด</button></article></section><section class="card"><h2>บันทึกการสมัคร</h2><select v-model="resumeId"><option value="">เลือก Resume</option><option v-for="r in state.resumes" :value="r.id">{{r.data.job.company}} · {{r.id.slice(0,8)}}</option></select><select v-model="applicationStatus"><option v-for="s in ['prepared','applied','interview','offer','rejected']">{{s}}</option></select><textarea v-model="applicationNotes" placeholder="หมายเหตุ"></textarea><button class="primary" :disabled="!resumeId||busy" @click="run(async()=>{await api('/applications','POST',{resumeId,status:applicationStatus,notes:applicationNotes});await refresh();message='บันทึกแล้ว'})">บันทึกสถานะ</button><p class="muted">บันทึกประวัติเท่านั้น ไม่มีการส่งใบสมัครอัตโนมัติ</p><article class="fact" v-for="a in state.applications"><b>{{a.data.company}} · {{a.data.title}}</b><p>{{a.data.status}} · {{new Date(a.createdAt).toLocaleString()}}</p><p>{{a.data.notes}}</p></article></section></div><section class="card"><h2>Generation Jobs</h2><article v-for="t in state.tasks" class="job-row"><div>{{t.type}} · {{t.status}}<p class="error" v-if="t.error">{{t.error}}</p></div><button v-if="t.status==='failed'" @click="run(async()=>track(await api('/tasks/'+t.id+'/retry','POST')))">Retry</button><button v-if="t.output?.assetId" @click="run(async()=>download(t.output.assetId))">ดาวน์โหลด</button><button v-if="['queued','running'].includes(t.status)" @click="track(t)">ติดตาม</button></article></section></main>
<footer>Local AI Resume Tailor · ตรวจทุกข้อความก่อนใช้สมัครงาน · ประมวลผล AI ผ่าน Ollama ของคุณ</footer>
</template>
</div>
</template>
